50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	
53	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	
62	/** Percentages are applied as integer arithmetic so that the final
63	 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
64	const addPercent = (amount: number, percent: number): number =>
65	  amount + (amount * percent) / 100;
66	
67	/** Rounds up — premiums round in the MHPCO's favour. */
68	const roundPremium = (amount: number): number => Math.ceil(amount);
69	
70	const COMPONENT_BLOCK_SIZE = 3;
71	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
72	
73	const COMPONENT_TYPES = ["rune", "moonstone"];
74	
75	const isComponent = (item: Item): boolean =>
76	  COMPONENT_TYPES.includes(item.type);
77	
78	const itemBasePremium = (item: Item): number =>
79	  BASE_PREMIUM_BY_TYPE[item.type];
80	
81	const countByType = (items: Item[]): Map<string, number> => {
82	  const counts = new Map<string, number>();
83	  for (const item of items) {
84	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
85	  }
86	  return counts;
87	};
88	
89	/** A block is exactly three alike components, priced as a unit rather than
90	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
91	const componentGroupBasePremium = (type: string, count: number): number =>
92	  count === COMPONENT_BLOCK_SIZE
93	    ? COMPONENT_BLOCK_BASE_PREMIUM
94	    : count * BASE_PREMIUM_BY_TYPE[type];
95	
96	const policyBasePremium = (items: Item[]): number => {
97	  const mainItems = items.filter((item) => !isComponent(item));
98	  const mainTotal = mainItems.reduce(
99	    (total, item) => total + itemBasePremium(item),
100	    0,
101	  );
102	
103	  let componentTotal = 0;
104	  for (const [type, count] of countByType(items.filter(isComponent))) {
105	    componentTotal += componentGroupBasePremium(type, count);
106	  }
107	
108	  return mainTotal + componentTotal;
109	};
110	
111	const quote = (items: Item[]): QuoteResult => {
112	  const basePremium = policyBasePremium(items);
113	  const modifiedPremium = addPercent(
114	    basePremium,
115	    FIRST_INSURANCE_SURCHARGE_PERCENT,
116	  );
117	  // The processing fee is added last, after all percentage modifiers.
118	  const premium = modifiedPremium + PROCESSING_FEE;
119	  return { premium: roundPremium(premium) };
120	};
121	
122	const runStep = (step: Step): StepResult => {
123	  if (step.op === "quote") return quote(step.items);
124	  throw new Error(`Unsupported step: ${step.op}`);
125	};
126	
127	export const runScenario = (scenario: Scenario): ScenarioResult => {
128	  const results = scenario.steps.map(runStep);
129	  return { results };
130	};
